parameters.jsCode:
return items.map(s => ({
  json: {
    ...s.json,
    color: s.json.signal_type.includes('BUY') ? 3066993 : 15158332,
    emoji: s.json.signal_type.includes('BUY') ? '🟢' : '🔴',
    analysts: JSON.parse(s.json.recent_analyst_calls_json || '[]')
  }
}));

parameters.value:
=[{
  "title": "{{$json.emoji}} {{$json.signal_type.replace('_', ' ')}}: {{$json.ticker}}",
  "color": {{$json.color}},
  "fields": [
    {
      "name": "Price at Signal",
      "value": "${{$json.price_at_signal.toFixed(2)}}",
      "inline": true
    },
    {
      "name": "Historical Win Rate",
      "value": "{{$json.win_rate ? $json.win_rate.toFixed(0) + '%' : 'N/A'}}",
      "inline": true
    },
    {
      "name": "Avg Peak Return",
      "value": "{{$json.avg_peak ? '+' + $json.avg_peak.toFixed(1) + '%' : 'N/A'}}",
      "inline": true
    },
    {
      "name": "Top Analyst Sentiment",
      "value": "{{$json.analysts.length > 0 ? $json.analysts[0].firm + ': ' + $json.analysts[0].action : 'No recent analyst data.'}}"
    }
  ],
  "footer": {
    "text": "Sovson Analytics • {{$json.signal_date}}"
  }
}]
